    {
      "id": "inflation-spiral-narrative",
      "insight": "Show the temporal interplay among CPI inflation, wage growth, the federal funds rate, and real wage growth from 2021 to 2024, emphasizing how these four series move relative to each other over time"
    },
    {
      "id": "rate-hike-lag",
      "insight": "Highlight the visible delay between the start of federal funds rate increases and the subsequent decline in CPI inflation, making the lag period visually prominent"
    },
    {
      "id": "real-wage-squeeze",
      "insight": "Emphasize the period where real wage growth turns negative — when CPI inflation exceeds nominal wage growth — and when it recovers back to positive territory"
    },
    {
      "id": "peak-inflation-zone",
      "insight": "Draw attention to the mid-2022 peak inflation zone and how all four indicators behave around that critical period"
    },
    {
      "id": "fed-rate-trajectory",
      "insight": "Visually distinguish the federal funds rate trajectory from the other series, showing its step-function-like climb from near-zero to above 5%"
    }
  ]
